return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ha','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Yana adana fayilolin WordPress da rumbun adana bayanai zuwa ma\'ajiyar ku — Dropbox, Google Drive, Cloudflare R2, Amazon S3 ko kowane bucket mai dacewa da S3 — yana dawo da su lokaci guda, kuma yana shigo da madadin da wasu plugin na adanawa da ƙaura suka yi.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Ajiye bayanan sirri','Get Pro: schedules, several storages, encryption'=>'Sami Pro: jadawali, ma\'ajiyoyi da yawa, rufaffen bayani','Working…'=>'Ana aiki…','Finished'=>'Gama','Failed'=>'Ya faskara','Cancelled'=>'An soke','Cancel'=>'Soke','Restore'=>'Mayar','Delete'=>'Goge','Delete this backup from your storage? This cannot be undone.'=>'A goge wannan ajiyar daga ma\'ajiyar ku? Ba za a iya soke wannan ba.','No backups yet. Press “Back up now” to make the first one.'=>'Babu adana bayanan sirri tukuna. Latsa "Ajiye bayanai yanzu" domin yin na farko.','Reading your storage…'=>'Ana karanta ma\'ajiyar bayananku…','a complete backup, as opposed to an incremental oneFull backup'=>'Cikakken ajiya','a backup holding only what changed since an earlier oneIncremental backup'=>'Ajiye bayanai na ƙari','Encrypted'=>'Boyayye','From another site'=>'Daga wani shafi','Database'=>'Tattalin bayanai','Files'=>'Fayiloli','Uploading %1$s: %2$s%%'=>'Ana loda %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Shiga Dropbox a cikin taga da ya buɗe, sannan liƙa lambar da Dropbox ya nuna maka:','Saved.'=>'An ajiye.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Cire wannan makoma daga manhajar? Ba za a share bayanan da aka ajiye a ciki ba.','Reload the page to see the restored site.'=>'Sake loda shafin don ganin shafin da aka dawo da shi.','Storage'=>'Wurin ajiya','Import & migrate'=>'Shigo da ƙaura','Settings'=>'Saituna','Sections'=>'Sassuka','Google Drive is connected.'=>'An haɗa Google Drive.','Google Drive could not be connected.'=>'Ba a iya haɗa Google Drive ba.','Details'=>'Cikakkun bayanai','Back up now'=>'Ajiye kwafi yanzu','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Ajiyayyun bayanan suna tafiya ne zuwa ma\'ajiyarku, ba wannan uwar garken ba. Da farko <a href="%s">haɗa ma\'ajiyarku</a>.','What to back up'=>'Abin da za a ajiye','Files and database'=>'Fayiloli da rumbun adana bayanai','Database only'=>'Taskar bayanai kawai','Files only'=>'Fayiloli kawai','Note (optional)'=>'Bayanin kula (na zaɓi)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Ana loda kowane bangare zuwa ma\'ajiyarka kuma a cire shi daga wannan uwar garken kafin a yi na gaba, don haka adana bayanan ba ya taba daukar sarari a kan bakuncin ka ba.','Your backups'=>'Ajiyayyun bayanan ku','Refresh'=>'Wartsake','Restore this backup'=>'Mayar da wannan ajiyar','Passphrase'=>'Kalmar sirri','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Na fahimci wannan zai maye gurbin fayiloli da rumbun adana bayanai na wannan shafi da na madadin. Fayilolin da ba sa cikin madadin za a ajiye su.','Recent activity'=>'Ayyukan kwanan nan','Backup'=>'Ajiye bayanai','Restore / import'=>'Mayar / shigo da','Running'=>'Yana aiki','Your storage'=>'Wurin ajiyarka' . "\0" . 'Wuraren ajiyarka','No storage yet. Choose where your backups go below.'=>'Babu ma\'aji tukuna. Zaɓi inda adananku zai tafi a ƙasa.','Ready'=>'A shirye','Not connected'=>'Ba a haɗa ba','Connect'=>'Haɗa','Test'=>'Gwaji','Edit'=>'Gyara','Remove'=>'Cire','Add storage'=>'Ƙara ma\'ajiya','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Ajiyar bayanan na tafiya zuwa wurin ajiya ɗaya. Don amfani da wani daban, gyara ko cire na saman.','Kind of storage'=>'Nau\'in ajiya','Name (for you)'=>'Suna (na ka)','Provider'=>'Mai bayarwa','Cloudflare account id'=>'ID na asusun Cloudflare','Endpoint address'=>'Adireshin endpoint','Region'=>'Yanki','Bucket'=>'Kofi','Access key id'=>'ID na maɓallin shiga','Secret access key'=>'Kulle na sirri na samun dama','Leave empty to keep the saved key'=>'Bar shi a wofi don adana maɓallin da aka ajiye','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Don Cloudflare R2: a cikin dashboard na Cloudflare buɗe R2, ƙirƙiri bucket, sannan “Manage R2 API tokens” → ƙirƙiri token mai Object Read & Write don wannan bucket ɗin, sannan kwafi access key id da secret a nan.','Dropbox app key'=>'Mabuɗin manhajar Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Ƙirƙiri manhaja a dropbox.com/developers/apps (Scoped access, App folder) tare da izinin files.content.read, files.content.write da files.metadata.read, sannan kwafi App key ɗin sa a nan. Ajiye, sannan danna Connect.','OAuth client id'=>'ID na abokin ciniki na OAuth','OAuth client secret'=>'Sirrin abokin ciniki na OAuth','Leave empty to keep the saved secret'=>'Bar shi a wofi don adana asirin da aka ajiye','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'A cikin Google Cloud Console, kunna Google Drive API, sannan ƙirƙiri abokin ciniki na OAuth na nau\'in "Web application" tare da wannan adireshin azaman izini na turawa URI:','Save, then press Connect. The plugin only sees the files it creates.'=>'Ajiye, sannan ka danna Haɗa. Manhajar tana ganin fayilolin da ta ƙirƙira ne kawai.','Folder inside the storage (optional)'=>'Foda a cikin ma\'ajiya (na zaɓi)','Save storage'=>'Ajiye ma\'ajiya','Import a backup from another plugin or host'=>'Shigo da ajiye na baya daga wani plugin ko mai masauki','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Shigo da shafi daga ma\'ajiyar da aka yi ta hanyar UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, ko kowane tarihin zip/tar na shafin WordPress tare da zubar da .sql dinsa. Abun cikin yana shiga wp-content kuma rumbun adana bayanai yana maye gurbin na wannan shafin; ana sauya adiresoshin zuwa na wannan shafin kai tsaye.','Upload from your computer'=>'Loda daga kwamfutarka','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Zaɓi kowane fayil na ma\'ajiyar kariya a lokaci ɗaya (UpdraftPlus yana yin da yawa). Ana aika manyan fayiloli a ƙananan guntu, don haka iyakar lodawa ta mai masaukin ku ba ta aiki.','Or from links (Google Drive, Dropbox or any download address)'=>'Ko daga hanyoyin haɗi (Google Drive, Dropbox ko kowane adireshin saukewa)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Hanyar haɗi ɗaya a kowane layi. Don Google Drive da Dropbox, raba fayil ɗin tare da "duk wanda ke da hanyar haɗin" sannan liƙa wannan hanyar haɗin; sake kashe rabawa daga baya.','Or a file already on this server'=>'Ko fayil ɗin da ya riga ya kasance a kan wannan sabar','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Loda rumbunan adana bayanai ta hanyar FTP ko manajan fayil na mai masaukin ku zuwa %s sannan ku sake loda wannan shafi.','Or a deploy code from another site'=>'Ko lambar tura aiki daga wani shafin','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Idan wani shafi ya ba ku lambar tura Zinn® Backups, manna ta anan don kwafi wannan ma\'ajiyar zuwa wannan shafin ba tare da raba makullin ajiyar sa ba. Lambar tana aiki na \'yan sa\'o\'i; ɗauke ta kamar kalmar sirri.','Passphrase (only if that backup is encrypted)'=>'Kalmar sirri (kawai idan an ɓoye bayanan ajiya)','Import'=>'Shigo da','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Na fahimci shigo da bayanan zai maye gurbin abubuwan da ke cikin wannan rukunin yanar gizon da kuma rumbun adana bayanai. Bayan haka, shiga da asusu daga shafin da aka shigo da shi.','Moving to Zinn® hosting?'=>'Kuna komawa zuwa karɓar baƙuncin Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® na iya ƙaura da rukunin yanar gizonku daga tsohon mahallin ku dominku. Idan tsohon mahallin ku bai ba ku damar shiga FTP, SSH ko rukunin sarrafawa ba, shigar da Zinn® Migrate a tsohon rukunin yanar gizon; yana ƙirƙirar rumbun adana bayanai ɗaya wanda za ku iya shigo da shi anan ko mika shi ga Zinn®.','What goes into a backup'=>'Abin da ke shiga cikin ma\'ajiyar wucin gadi','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Haɗa fayilolin WordPress na asali (wp-admin, wp-includes). Yawanci ba a buƙata: ana iya sake shigar da WordPress a kowane lokaci.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Kuma bar waɗannan manyan fayiloli ko fayiloli (ɗaya a kowane layi, dangane da babban fayil na WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Koyaushe ana barin su: ma\'ajiyar cache, sararin aiki na sabuntawa, da kuma manyan fayilolin ajiya na sauran kayan aikin madadin kansu:','Size of each part (MB)'=>'Girmar kowane sashi (MB)','Save settings'=>'Ajiye saituna','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Ba a iya buɗe wani ɓangare na ajiyar kariya domin rubutawa ba. Bincika cewa wp-content yana da sarari.','A backup part could not be written. Check that wp-content has free space.'=>'Ba a iya rubuta wani ɓangare na ajiyar ba. Duba ko wp-content yana da sarari.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Fara haɗa wurin ajiya a shafin Storage tukunna: ana adana kwafin bayanan a cikin ma\'ajiyarku ne, ba a kan wannan uwar garken ba.','Multisite networks are not supported yet.'=>'Ba a goyi bayan hanyoyin sadarwa na multisite ba tukuna.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP na wannan uwar garken ba ta da ƙarin faɗaɗa na ZipArchive. Nemi mai masaukin ku ya kunna shi.','Starting'=>'Ana farawa','Listing files'=>'Ana jera fayiloli','Backing up the database'=>'Ana adana bayanan rumbun adana bayanai','Packing files'=>'Ana tattara fayiloli','Uploading to your storage'=>'Ana lodawa zuwa ma\'ajiyarku','Finishing'=>'Ana gamawa','The backup reached an unknown stage.'=>'Ajiye bayanan ya kai wani mataki da ba a sani ba.','Backup %s started.'=>'An fara ajiye kofin %s.','Found %1$s files (%2$s).'=>'An sami fayiloli guda %1$s (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Tushen bayanai: tebura %1$d, layuka %2$s, %3$s an matse.','Backup complete: %1$s stored in %2$d destination.'=>'An kammala adana bayanai: an adana %1$s a makoma %2$d.' . "\0" . 'Ajiye bayanan ya kammala: An adana %1$s a wurare %2$d.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Ba a iya cire wasu ɓangarorin da aka riga aka ɗora daga ma\'ajiyar ku ba; suna cikin babban fayil ɗin ajiya wanda ba a kammala ba kuma ba za a taɓa bayar da su don dawo da su ba.','A storage destination was removed while the backup was running.'=>'An cire wurin ajiya yayin da ake gudanar da aikin ajiye bayanan.','That is not a backup folder.'=>'Wannan ba babban fayil ɗin ajiya ba ne.','That storage destination is no longer saved on this site.'=>'Wannan wurin ajiyar ba a sake adana shi a wannan rukunin yanar gizon ba.','Later incremental backups are built on this one. Delete those first.'=>'Karin madadin ajiyar bayanan na baya sun dogara ne a kan wannan. Da farko share wadannan.','This file is not an encrypted Zinn® Backups file.'=>'Wannan fayil ɗin ba ɓoyayyen fayil ɗin Zinn® Backups ba ne.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Ba a iya buɗe ɓoyayyen bayanin ajiyar ba: kalmar wucewa ba daidai ba ce ko kuma fayil ɗin ya lalace.','The encrypted backup file is incomplete.'=>'Fayil ɗin ajiyar na\'ura mai rufaffen sirri bai cika ba.','The database file could not be written. Check that wp-content has free space.'=>'Ba a iya rubuta fayil ɗin ma’ajiyar bayanai ba. Duba ko akwai sarari a cikin wp-content.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Wannan ba lambar turawa ba ce. Lambar turawa tana farawa ne da zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Wannan lambar tura aikin ta lalace. Sake kwafarta daga ɗayan rukunin yanar gizon.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Lambar tura aikin ta kare ko kuma an goge ajiyar tsaronta. Samar da sabuwar lamba a dayan shafin.','That deploy code does not point at a Zinn® Backups backup.'=>'Wannan lambar tura aiki ba ta nuna wani ajiyar Zinn® Backups ba.','The deploy code has expired. Make a new code on the other site.'=>'Lambar tura aikin ta ƙare. Ƙirƙiri sabuwar lamba a ɗayan shafin.','The server stopped honouring partial downloads. Start the import again.'=>'Sabar ta daina karɓar saukarwa marar cika. Sake fara shigarwar.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Mahaɗin ya buɗe shafin yanar gizo maimakon fayil. Don Google Drive da Dropbox, raba fayil ɗin tare da "kowa mai mahaɗin" sannan ka manna wannan mahaɗin.','The link answered with HTTP %d.'=>'Mahaɗin ya amsa da HTTP %d.','The file list could not be written.'=>'Ba a iya rubuta jerin fayil ɗin ba.','The storage service could not be reached: %s'=>'Ba a iya samun sabis ɗin ajiya ba: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ya amsa da HTTP %2$d: %3$s','no details given'=>'Ba a bayar da cikakkun bayanai ba','You are not allowed to manage backups.'=>'Ba a ba ku izinin sarrafa ajiyar waje ba.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Yi alama a akwatin don tabbatar da cewa mayar da bayanan zai maye gurbin fayiloli da rumbun adana bayanai na wannan rukunin yanar gizo.','Save the destination first.'=>'Ajiye makomar da farko.','Connected: a test file was written and removed.'=>'An haɗa: an rubuta fayil ɗin gwaji kuma an cire shi.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Da farko shigar da maɓallin manhaja na manhajar Dropbox ɗinku (duba matakan da ke kusa da fom ɗin).','This kind of storage does not sign in.'=>'Irin wannan ma\'ajiya ba ta shiga.','The sign-in expired. Press Connect again.'=>'Lokacin shiga ya ƙare. Danna Haɗa kuma.','Dropbox is connected.'=>'An haɗa Dropbox.','Settings saved.'=>'An ajiye saitunan.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Wani aikin ajiye bayanan sirri, mayarwa ko shigo da shi na gudana. Jira ya kammala, ko kuma ka soke shi.','The upload was not started properly. Start again.'=>'Ba a fara loda fayil ɗin yadda ya kamata ba. Sake farawa.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Guntun bai iso ba. Sabar ɗinka na iya iyakance girman lodi; sake gwadawa.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Yi alama a akwatin don tabbatar da cewa shigo da kaya yana maye gurbin abun ciki da bayanan wannan rukunin yanar gizon.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Zaɓi rumbun ajiya da za a shigo da shi: loda shi, liƙa hanyar haɗi, ko zaɓi ɗaya daga babban fayil ɗin shigo da kaya.','Hosting customer? Get %1$d%% off %2$s'=>'Abokin cinikin hosting? Samu rangwamen %1$d%% akan %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'A matsayin abokin cinikin karɓar baƙuncin Zinn Digital® kuna samun lambar sirri don rangwamen %d%% akan biyan kuɗin ku na farko. Sabuntawa suna kan farashin al\'ada.','Get my %d%% code and go to checkout'=>'Sami lambar %d%% tawa kuma je wurin biya','Sorry, you are not allowed to do that.'=>'Yi haƙuri, ba a ba ku izinin yin hakan ba.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Wannan rangwamen na abokan ciniki ne masu tsarin ɗaukar nauyin shafi (hosting) da aka biya kuma yake cikin kyakkyawan yanayi. Gwajin kyauta bai cancanta ba.','You have already used your hosting-customer discount for this plugin.'=>'Kun riga kun yi amfani da rangwamen abokin ciniki na bakuncin don wannan manhaja.','We could not get your code just now. Please try again in a few minutes.'=>'Ba mu iya samun lambar ku a yanzu ba. Da fatan za a sake gwadawa nan da \'yan mintuna.','Reading the backup'=>'Ana karanta madadin','Downloading the archive'=>'Ana sauke rumbun adana bayanai','Recognising the archive'=>'Ana gane ma\'adanar bayanai','Restoring files'=>'Ana maido da fayiloli','Downloading the database'=>'Ana sauke rumbun adana bayanai','Restoring the database'=>'Ana maido da rumbun adana bayanai','Updating the site address'=>'Ana sabunta adireshin shafin','Switching to the restored database'=>'Ana canzawa zuwa ma\'adanar bayanai da aka dawo da ita','The restore reached an unknown stage.'=>'Mayarwar ta kai wani mataki da ba a sani ba.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Wannan babban fayil ɗin ba shi da cikakken madadin Zinn® Backups a ciki (bayanin bayyanawa ya ɓace).','This backup is encrypted. Enter its passphrase to restore it.'=>'Wannan ajiyar an ɓoye ta. Shigar da kalmar sirrinta don dawo da ita.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Wannan ajiyar wucin-gadi tana buƙatar ajiyar %s, wacce ba ta nan a rumbun ajiya.','Restoring the backup of %1$s (%2$d file parts).'=>'Ana mayar da ma\'ajiyar %1$s (%2$d sassan fayil).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Ba a iya sake rubuta fayil ɗin %1$s ba saboda wannan rukunin yanar gizon ba a ba shi izinin canza shi ba, kuma an bar shi yadda yake: %2$s' . "\0" . 'Ba a iya sake rubuta fayiloli %1$s ba saboda ba a ba wannan rukunin yanar gizon izinin canza su ba, kuma an bar su yadda suke: %2$s','Restored %s files.'=>'An maido da fayiloli %s.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s bai yi daidai da lambar bincikensa ba bayan saukarwa. Kofin da ke ajiye zai iya zama ya lalace.','%s did not arrive. Upload it again.'=>'%s bai iso ba. Sake loda shi.','Recognised: %s.'=>'An gane: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'An shigo da fayiloli %1$s zuwa wp-content (an bar %2$s: caches, drop-ins da manyan fayilolin sauran plugins na ajiyar gani).','The archive has no database dump, so only files were imported.'=>'Rumbun adana bayanan ba shi da juji na rumbun bayanai (database dump), don haka fayiloli kawai aka shigo da su.','Database restored into %d temporary tables.'=>'An maido da rumbun adana bayanai zuwa jadawalan wucin gadi guda %d.','%s has no WordPress tables in it and was skipped.'=>'%s ba shi da kowane teburan WordPress a cikinsa kuma an tsallake shi.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Rumbun adana bayanan ajiyar ba shi da teburan WordPress, don haka ba a canza komai ba.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Wannan ajiyar na hanyar sadarwa ce ta shafuka da yawa (multisite). Ba a goyi bayan maido da hanyar sadarwa zuwa shafi guda ɗaya ba.','Moving the content from %1$s to %2$s.'=>'Ana matsar da abun ciki daga %1$s zuwa %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'An kammala mayarwa. Idan an fitar da ku, shiga tare da asusu daga shafin da aka mayar.','Restore complete.'=>'An kammala maido da aiki.','%1$s — trying again in %2$d seconds.'=>'%1$s — za a sake gwadawa nan da daƙiƙa %2$d.','Cancelled.'=>'An soke.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Ajiye bayanan baya yana tafiya zuwa makoma ɗaya ta ajiya. Gyara ko cire wanda kake da shi don amfani da wani daban.','The database file could not be opened.'=>'Ba a iya buɗe fayil ɗin ma\'ajiyar bayanai ba.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Taskar bayanai ta ki amincewa da wata sanarwa daga madadin: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Ba a iya canza teburan da aka dawo da su ba: %s. Shafinku bai canza ba.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Babu babban fayil da za a iya rubutawa don fayilolin ajiya na ɗan lokaci. Sanya wp-content ya zama mai yiwuwar rubutawa kuma sake gwadawa.','Could not create a folder for this job.'=>'Ba a iya ƙirƙirar babban fayil don wannan aikin ba.','%s — guides and services'=>'%s — jagorori da ayyuka','User guides'=>'Littattafan jagora na mai amfani','Read the %s user guide'=>'Karanta jagorar mai amfani ta %s','Hide this'=>'Ɓoye wannan','Zinn® hosting for WordPress'=>'Baƙuncin Zinn® don WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, ajiyar bayanan yau da kullun, sauya matsuguni kyauta da kuma allon sarrafawa da aka gina don mutanen da ke gudanar da shafuka fiye da ɗaya.','The Zinn® marketplace'=>'Kasuwar Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Sayi kuma sayar da shafukan da aka kafa, yankuna da kuma sanya hanyoyin haɗi, tare da ajiye kuɗin cikin aminci har sai ɓangarorin biyu sun gamsu.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — ɗauki mutanen da wannan ne sana\'arsu','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Kasuwar mu ta masu zaman kansu ta duniya: bincika sama da ayyuka 10,000 da aka shirya daga marubuta, masu ƙira, masu haɓakawa da ƙwararrun SEO, ko sanya aiki kuma bari su yi tayi.','See the Zinn Digital® release notes.'=>'Duba bayanan sakin Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Sabis ɗin sabuntawa na Zinn® bai fitar da hanyar saukewa don wannan sabuntawa ba. Bincika cewa wannan rukunin yanar gizon zai iya isa ga dandalin Zinn®, sannan a sake gwadawa.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ba a iya sauke sabuntawar daga sabis ɗin sabuntawa na Zinn® (%s) ba. Sake gwadawa nan da \'yan mintuna.','The downloaded update failed its integrity check and was not installed.'=>'Sabuntawar da aka saukar ta gaza wajen tantance amincinta kuma ba a shigar da ita ba.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Ba a iya buɗe rumbun adana bayanai na zip ɗin ba. Wataƙila ya lalace ko kuma bai cika ba.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Wannan fayil na .wpress yana amfani da tsarin da ba za mu iya karantawa ba (yana iya kasancewa All-in-One WP Migration ne ya matse shi ko ya ɓoye shi). Sake fitar da shi ba tare da ɓoyewa ba.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Wannan fayil ɗin Duplicator “DupArchive” (.daf) ne. A cikin Duplicator, sake gina kunshin tare da saita tsarin taskar zuwa ZIP, sannan shigo da shi.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Wannan ma\'ajiyar bayanai ta UpdraftPlus an ɓoye ta. Buɗe ta a cikin UpdraftPlus (ko kashe ɓoye bayanan sannan ka sake yin ma\'ajiya), sannan ka shigo da ita.','Database dump'=>'Zubar da rumbun adana bayanai','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s ba rumbun adana bayanan baya ba ne da za mu iya karantawa (zip, tar, tar.gz, .wpress, .sql ko .sql.gz).','Website archive'=>'Taskar shafin yanar gizo','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s ba shi da wani abun ciki na WordPress (babu babban fayil na wp-content kuma babu zubar da rumbun adana bayanai).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Wannan fayil ɗin .wpress yana da rufaffen sirri ko matsewa ta All-in-One WP Migration. Sake fitar da shi tare da kashe ɓoye sirri da matsawa, sannan shigo da wannan.','Other S3-compatible storage'=>'Wurin ajiya daban mai dacewa da S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 ko mai dacewa da S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Ba a iya karanta makullin ajiya a wannan rukunin yanar gizon ba. Sake shigar da maɓallin sirri a shafin Ma\'ajiya.','This kind of storage is not known.'=>'Ba a san irin wannan ma\'ajiyar ba.','Choose a kind of storage.'=>'Zaɓi nau\'in ajiya.','Enter the bucket name and the access key.'=>'Shigar da sunan bucket da maɓallin shiga.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Shigar da ID na asusun Cloudflare ɗinka (ko cikakken endpoint na R2).','Enter the endpoint address of your storage.'=>'Shigar da adireshin madogarar ma\'ajiyarka.','Enter the OAuth client id from your Google Cloud project.'=>'Shigar da OAuth client id daga aikin Google Cloud naka.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox bai dawo da alamar sabuntawa ba. Sake fara haɗin.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Ba a haɗa Dropbox ba. Sake haɗa shi a shafin Adana.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google bai dawo da alamar sabuntawa (refresh token) ba. Cire wannan rukunin yanar gizon daga damar shiga na ɓangare na uku a asusunka na Google sannan ka sake haɗawa.','That file is not in Google Drive any more.'=>'Wannan fayil ɗin baya cikin Google Drive kuma.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Ba a haɗa Google Drive ba. Sake haɗa shi a shafin Ma\'ajiya.','The storage service did not start the upload.'=>'Ayyukan ajiya ba su fara lodawa ba.','The storage service sent a reply that could not be read.'=>'Sabis ɗin ajiya ya aiko da amsar da ba a iya karantawa ba.','A temporary backup file could not be read.'=>'Ba a iya karanta wani fayil na ajiye bayanai na ɗan lokaci ba.','A deploy link is read-only.'=>'Hanyar turawa ta karantawa ce kawai.','The deploy code has no link for a file this backup needs.'=>'Lambar tura aikin ba ta da hanyar haɗi don fayil ɗin da wannan madadin ke buƙata.','The deploy link'=>'Hanyar tura aiki']];